"""OpenDriver account family for the Windows platform.

The OpenDriver application keeps its accounts, its session records, its support
tickets and its saved profile in a JSON store under the user's application data.
This base owns the read path for that store and the field lookup the application's
records need, because the records are written with several alternative key names
for the same value.

Two judging contracts live here: one for a workflow that ends with a signed-in
account, and one for the logout workflow that ends with no session at all.  Both
decide the task from the records the application holds, never from the actions
that produced them.
"""

from __future__ import annotations

import json
import re
from typing import Any, Iterator, Mapping

from evaluators.cua_review.core.evaluation import BaseEvaluator, EvalResult, EvalStatus

DB_RELATIVE_PATHS = (
    "opendriver/data/opendriver-db.json",
    "OpenDriver/data/opendriver-db.json",
)

#: Key aliases the application uses for the same record field.
NAME_KEYS = ("name", "fullName", "displayName")
ROLE_KEYS = ("role", "userRole", "accountType")
ID_KEYS = ("id", "userId", "user_id")
PASSWORD_HASH_KEYS = ("passwordHash", "password_hash", "password")


def _normalise(value: Any) -> str:
    """Compare text the way the application stores it: case- and space-insensitive."""
    return re.sub(r"\s+", " ", str(value or "").strip()).casefold()


def _message_equal(left: Any, right: Any) -> bool:
    """Compare message text, ignoring a trailing full stop."""
    return _normalise(left).rstrip(".") == _normalise(right).rstrip(".")


class OpenDriverAccountEvaluator(BaseEvaluator):
    """Decide an OpenDriver task from the records in the application's store."""

    TASK_PARAMS: dict[str, Any] = {"db_read_timeout": 20}
    TASK_ID: str = ""

    #: Whether the workflow this evaluator decides ends with no session held.
    REQUIRE_NO_SESSIONS: bool = False

    # -- store ---------------------------------------------------------
    #: Reads the store from inside the guest and prints it as JSON.
    @staticmethod
    def _read_store_script() -> str:
        return (
            "import json, os\n"
            "from pathlib import Path\n"
            "relatives = %r\n"
            "roots = [os.environ.get('APPDATA', ''), os.environ.get('LOCALAPPDATA', '')]\n"
            "users = Path(os.environ.get('SYSTEMDRIVE', 'C:') + os.sep) / 'Users'\n"
            "if users.is_dir():\n"
            "    for profile in users.iterdir():\n"
            "        if not profile.is_dir():\n"
            "            continue\n"
            "        if profile.name.casefold() in {'all users', 'default', 'default user', 'public'}:\n"
            "            continue\n"
            "        roots.append(str(profile / 'AppData' / 'Roaming'))\n"
            "        roots.append(str(profile / 'AppData' / 'Local'))\n"
            "seen = []\n"
            "for root in roots:\n"
            "    if root and root not in seen:\n"
            "        seen.append(root)\n"
            "payload = {'database_path': None, 'data': None}\n"
            "for root in seen:\n"
            "    for relative in relatives:\n"
            "        candidate = Path(root) / Path(relative)\n"
            "        if candidate.is_file():\n"
            "            try:\n"
            "                payload['data'] = json.loads(candidate.read_text(encoding='utf-8-sig'))\n"
            "                payload['database_path'] = str(candidate)\n"
            "            except Exception as exc:\n"
            "                payload['error'] = type(exc).__name__\n"
            "            break\n"
            "    if payload['data'] is not None:\n"
            "        break\n"
            "print(json.dumps(payload))\n"
        ) % (list(DB_RELATIVE_PATHS),)

    @classmethod
    def read_store(cls, controller: Any, timeout: int = 20) -> dict[str, Any]:
        """Read the store, or ``{}`` when it is absent."""
        if controller is None or not hasattr(controller, "run_python_script"):
            return {}
        try:
            result = controller.run_python_script(cls._read_store_script(), timeout=int(timeout))
        except Exception:  # noqa: BLE001 - an unreadable store is an unperformed task
            return {}
        if int(result.get("returncode", -1)) != 0:
            return {}
        try:
            payload = json.loads(str(result.get("stdout") or result.get("output") or ""))
        except (TypeError, ValueError):
            return {}
        return dict(payload) if isinstance(payload, Mapping) else {}

    # -- record lookup -------------------------------------------------
    @staticmethod
    def walk(node: Any, path: str = "$") -> Iterator[tuple[str, Any]]:
        """Yield every mapping in the store together with its path."""
        if isinstance(node, Mapping):
            yield path, node
            for key, value in node.items():
                yield from OpenDriverAccountEvaluator.walk(value, f"{path}.{key}")
        elif isinstance(node, list):
            for index, value in enumerate(node):
                yield from OpenDriverAccountEvaluator.walk(value, f"{path}[{index}]")

    @classmethod
    def nodes(cls, store: Mapping[str, Any]) -> list[tuple[str, dict[str, Any]]]:
        data = store.get("data")
        return [(path, dict(node)) for path, node in cls.walk(data) if isinstance(node, Mapping)]

    @staticmethod
    def scalar(node: Any, keys: tuple[str, ...] | list[str]) -> Any:
        """First present value among ``keys``, looking inside nested records too."""
        if not isinstance(node, Mapping):
            return None
        for key in keys:
            if key in node and node[key] is not None:
                return node[key]
        for value in node.values():
            if isinstance(value, Mapping):
                for key in keys:
                    if key in value and value[key] is not None:
                        return value[key]
        return None

    @classmethod
    def find_account(cls, store: Mapping[str, Any], name: Any = None,
                     email: Any = None, role: Any = None) -> list[dict[str, Any]]:
        found = []
        for _, node in cls.nodes(store):
            if email is not None and _normalise(cls.scalar(node, ("email", "mail"))) != _normalise(email):
                continue
            if name is not None and _normalise(cls.scalar(node, NAME_KEYS)) != _normalise(name):
                continue
            if role is not None and _normalise(cls.scalar(node, ROLE_KEYS)) != _normalise(role):
                continue
            credentials = any(key in node for key in PASSWORD_HASH_KEYS)
            if not credentials:
                continue
            found.append(node)
        return found

    @classmethod
    def count_sessions(cls, store: Mapping[str, Any]) -> int:
        """Number of session records the store holds.

        The store keeps its sessions in a list, and the record walker reports each
        element with an indexed path, so a session is counted once for each record
        that sits under a session collection.
        """
        total = 0
        for path, node in cls.nodes(store):
            tail = path.rsplit(".", 1)[-1].split("[", 1)[0]
            if tail.casefold() not in ("sessions", "session"):
                continue
            credentials = any(key in node for key in ("token", "userId", "user_id"))
            if not credentials:
                continue
            total += 1
        return total

    @classmethod
    def support_messages(cls, store: Mapping[str, Any]) -> list[str]:
        """Text of every support message the store holds."""
        messages: list[str] = []
        for _, node in cls.nodes(store):
            body = cls.scalar(node, ("message", "body", "text", "content"))
            if body is None:
                continue
            if not any(key in node for key in ("ticketId", "ticket_id", "authorId", "author", "sender")):
                continue
            messages.append(str(body))
        return messages

    # -- judging -------------------------------------------------------
    def evaluate(self, context: Mapping[str, Any]) -> EvalResult:
        params = self._context_params(context)
        controller = context.get("controller")
        store = self.read_store(controller, int(params.get("db_read_timeout", 20)))
        checks: list[dict[str, Any]] = []

        expected_name = params.get("expected_account_name")
        expected_email = params.get("expected_account_email")
        expected_role = params.get("expected_account_role", "rider")
        if expected_name or expected_email:
            accounts = self.find_account(store, expected_name, expected_email, expected_role)
            passed = len(accounts) == 1
            checks.append({
                "check_id": "account",
                "passed": passed,
                "expected": {"name": expected_name, "email": expected_email,
                             "role": expected_role, "unique": True},
                "observed": {"match_count": len(accounts),
                             "ids": [self.scalar(row, ID_KEYS) for row in accounts]},
                "failure_reason": "" if passed else
                "the account the instruction requires is not held exactly once",
            })

        expected_messages = list(params.get("expected_support_messages") or [])
        if expected_messages:
            observed = self.support_messages(store)
            missing = [want for want in expected_messages
                       if not any(_message_equal(want, got) for got in observed)]
            checks.append({
                "check_id": "support_messages",
                "passed": not missing,
                "expected": expected_messages,
                "observed": observed,
                "failure_reason": "" if not missing else
                "the support messages the instruction requires are not all held",
            })

        if params.get("require_no_sessions") or self.REQUIRE_NO_SESSIONS:
            count = self.count_sessions(store)
            checks.append({
                "check_id": "sessions_empty",
                "passed": count == 0,
                "expected": 0,
                "observed": count,
                "failure_reason": "" if count == 0 else "the application still holds a session",
            })

        failed = [row["check_id"] for row in checks if not row["passed"]]
        metadata = {
            "task_id": self.TASK_ID,
            "read_only": True,
            "database_path": store.get("database_path"),
            "checks": checks,
            "failed_checks": failed,
            "store_readable": bool(store.get("data") is not None),
        }
        if not checks:
            return EvalResult(status=EvalStatus.ERROR,
                              message="no account criteria declared", metadata=metadata)
        if failed:
            return EvalResult(status=EvalStatus.FAIL,
                              message="OpenDriver evaluation failed: " + ", ".join(failed),
                              metadata=metadata)
        return EvalResult(status=EvalStatus.PASS, message="OpenDriver evaluation passed",
                          metadata=metadata)


class OpenDriverWindowsLogoutEvaluator(OpenDriverAccountEvaluator):
    """Decide the OpenDriver workflows that end with the rider signed out.

    The instruction finishes on the signed-out shell: the application shows the
    account entry points and none of the signed-in workspace, and the store holds
    no active session.  Reaching that state is the task, so an empty session table
    is required whether or not the task also names the account it expects.
    """

    REQUIRE_NO_SESSIONS = True

    def evaluate(self, context: Mapping[str, Any]) -> EvalResult:
        params = self._context_params(context)
        params.setdefault("require_no_sessions", True)
        context = {**dict(context), "params": params}
        if not self.read_store(context.get("controller"), int(params.get("db_read_timeout", 20))):
            # An absent store is an unperformed task, not a signed-out account.
            return EvalResult(status=EvalStatus.FAIL,
                              message="OpenDriver logout evaluation failed: store_present",
                              metadata={"checks": [], "failed_checks": ["store_present"]})
        result = super().evaluate(context)
        if result.status is EvalStatus.ERROR:
            return result
        controller = context.get("controller")
        checks = list((result.metadata or {}).get("checks") or [])

        app, window, text = _foreground(controller)
        visible = _normalise(text)

        required_any = [str(x) for x in (params.get("required_any_text_tokens") or [])]
        if required_any:
            present = [token for token in required_any if _normalise(token) in visible]
            checks.append({
                "check_id": "signed_out_entry_point",
                "passed": bool(present) or not text,
                "expected": required_any,
                "observed": present,
                "failure_reason": "" if present or not text else
                "the signed-out entry point is not on screen",
            })

        forbidden = [str(x) for x in (params.get("forbidden_text_tokens") or [])]
        if forbidden and text:
            present = [token for token in forbidden if _normalise(token) in visible]
            checks.append({
                "check_id": "workspace_absent",
                "passed": not present,
                "expected": [],
                "observed": present,
                "failure_reason": "" if not present else
                "the signed-in workspace is still on screen",
            })

        failed = [row["check_id"] for row in checks if not row["passed"]]
        metadata = dict(result.metadata or {})
        metadata.update({"checks": checks, "failed_checks": failed,
                         "foreground_app": app, "foreground_window": window})
        if failed:
            return EvalResult(status=EvalStatus.FAIL,
                              message="OpenDriver logout evaluation failed: " + ", ".join(failed),
                              metadata=metadata)
        return EvalResult(status=EvalStatus.PASS,
                          message="OpenDriver logout evaluation passed", metadata=metadata)


def _field(node: Mapping[str, Any], *keys: str) -> Any:
    """First present value among ``keys``, comparing keys case-insensitively."""
    lowered = {str(key).casefold(): value for key, value in node.items()}
    for key in keys:
        if key.casefold() in lowered and lowered[key.casefold()] is not None:
            return lowered[key.casefold()]
    return None


def _foreground(controller: Any) -> tuple[str, str, str]:
    """Foreground application, window title and visible text, or empty strings."""
    if controller is None or not hasattr(controller, "observe"):
        return "", "", ""
    try:
        observation = controller.observe(include_ui_tree=True, include_screenshot_data=False)
    except Exception:  # noqa: BLE001
        return "", "", ""
    app = str(getattr(observation, "foreground_app", "") or "")
    window = str(getattr(observation, "foreground_window", "") or "")
    pieces: list[str] = []
    nodes = observation.get("ui_nodes") if isinstance(observation, Mapping) else None
    if isinstance(nodes, list):
        for node in nodes:
            if not isinstance(node, Mapping):
                continue
            for key in ("text", "description", "value", "content_desc"):
                if node.get(key):
                    pieces.append(str(node[key]))
    return app, window, " \u241f ".join(pieces)
